"use client";

import type { ComponentProps, CSSProperties, ReactNode } from "react";
import { createContext, useContext } from "react";

import type { InlineAttachmentKnobStyle } from "@/components/control-ui/knob-contracts/inline-attachment-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export type InlineAttachmentState = "ready" | "pending" | "error";

type InlineAttachmentContextValue = { name: string; state: InlineAttachmentState };

type InlineAttachmentStyle = CSSProperties & InlineAttachmentKnobStyle;
type InlineAttachmentStyleProps<Props, Style> = Omit<Props, "style"> & { style?: CSSProperties & Style };

const InlineAttachmentContext = createContext<InlineAttachmentContextValue | null>(null);

function useInlineAttachmentContext() {
  const context = useContext(InlineAttachmentContext);
  if (!context) throw new Error("InlineAttachment compound components must be rendered inside <InlineAttachment>.");
  return context;
}

function defaultLabel(name: string, state: InlineAttachmentState) {
  if (state === "pending") return `Generating ${name}`;
  if (state === "error") return `${name} is unavailable`;
  return `Open attachment: ${name}`;
}

export type InlineAttachmentProps = InlineAttachmentStyleProps<ComponentProps<"button">, InlineAttachmentKnobStyle> & {
  name: string;
  state?: InlineAttachmentState;
  /** Width-to-height ratio of the reserved box — generated media knows its ratio before its pixels, so arrival never reflows the turn. */
  aspect?: number;
};

export function InlineAttachment({
  name,
  state = "ready",
  aspect = 1.26,
  disabled,
  className,
  children,
  style,
  "aria-label": ariaLabel,
  ...props
}: InlineAttachmentProps) {
  const attachmentStyle = { aspectRatio: aspect, ...style } satisfies InlineAttachmentStyle;

  return (
    <InlineAttachmentContext.Provider value={{ name, state }}>
      <button
        type="button"
        aria-label={ariaLabel ?? defaultLabel(name, state)}
        aria-busy={state === "pending" || undefined}
        disabled={disabled || state === "pending"}
        data-control-ui="inline-attachment"
        data-control-family="inline-attachment"
        data-slot="root"
        data-surface="panel"
        data-state={state}
        className={cn("group relative w-full max-w-72 cursor-pointer overflow-hidden disabled:cursor-default", className)}
        style={attachmentStyle}
        {...props}
      >
        {children}
      </button>
    </InlineAttachmentContext.Provider>
  );
}

export type InlineAttachmentMediaProps = ComponentProps<"div"> & {
  src?: string;
  alt?: string;
} & { style?: CSSProperties & InlineAttachmentKnobStyle };

function GeneratingPlaceholder() {
  return (
    <div
      aria-hidden="true"
      data-control-ui="inline-attachment"
      data-control-family="inline-attachment"
      data-slot="placeholder"
      className="size-full halftone"
    />
  );
}

function DocumentPlaceholder() {
  return (
    <div data-control-ui="inline-attachment" data-control-family="inline-attachment" data-slot="document" className="size-full">
      <div data-control-ui="inline-attachment" data-control-family="inline-attachment" data-slot="document-sheet" className="h-full">
        <div data-control-ui="inline-attachment" data-control-family="inline-attachment" data-slot="document-heading" />
        <div className="grid">
          <div data-control-ui="inline-attachment" data-control-family="inline-attachment" data-slot="document-line" data-width="long" />
          <div data-control-ui="inline-attachment" data-control-family="inline-attachment" data-slot="document-line" data-width="medium" />
          <div data-control-ui="inline-attachment" data-control-family="inline-attachment" data-slot="document-line" data-width="longest" />
          <div data-control-ui="inline-attachment" data-control-family="inline-attachment" data-slot="document-line" data-width="short" />
        </div>
        <div data-control-ui="inline-attachment" data-control-family="inline-attachment" data-slot="document-stamp" />
      </div>
    </div>
  );
}

function mediaContent({ state, src, alt, children }: { state: InlineAttachmentState; src?: string; alt: string; children?: ReactNode }) {
  if (state === "pending") return <GeneratingPlaceholder />;
  if (src) {
    return (
      <img
        src={src}
        alt={alt}
        loading="lazy"
        decoding="async"
        data-control-ui="inline-attachment"
        data-control-family="inline-attachment"
        data-slot="media-image"
        className="size-full object-cover"
      />
    );
  }
  return children ?? <DocumentPlaceholder />;
}

export function InlineAttachmentMedia({ src, alt, className, children, ...props }: InlineAttachmentMediaProps) {
  const { name, state } = useInlineAttachmentContext();

  return (
    <div
      data-control-ui="inline-attachment"
      data-control-family="inline-attachment"
      data-slot="image"
      className={cn("size-full", className)}
      {...props}
    >
      {mediaContent({ state, src, alt: alt ?? name, children })}
    </div>
  );
}

export type InlineAttachmentContentProps = InlineAttachmentStyleProps<ComponentProps<"div">, InlineAttachmentKnobStyle>;

export function InlineAttachmentContent({ className, ...props }: InlineAttachmentContentProps) {
  return (
    <div
      data-control-ui="inline-attachment"
      data-control-family="inline-attachment"
      data-slot="content"
      className={cn("absolute", className)}
      {...props}
    />
  );
}

export type InlineAttachmentTitleProps = ComponentProps<"div"> & { style?: CSSProperties & InlineAttachmentKnobStyle };

export function InlineAttachmentTitle({ children, className, ...props }: InlineAttachmentTitleProps) {
  const { name } = useInlineAttachmentContext();

  return (
    <div
      data-control-ui="inline-attachment"
      data-control-family="inline-attachment"
      data-slot="title"
      className={cn("truncate", className)}
      {...props}
    >
      {children ?? name}
    </div>
  );
}

export type InlineAttachmentDescriptionProps = InlineAttachmentStyleProps<ComponentProps<"div">, InlineAttachmentKnobStyle>;

export function InlineAttachmentDescription({ className, ...props }: InlineAttachmentDescriptionProps) {
  return (
    <div
      data-control-ui="inline-attachment"
      data-control-family="inline-attachment"
      data-slot="description"
      className={cn("truncate", className)}
      {...props}
    />
  );
}

export type InlineAttachmentActionsProps = ComponentProps<"div"> & { style?: CSSProperties & InlineAttachmentKnobStyle };

export function InlineAttachmentActions({ className, ...props }: InlineAttachmentActionsProps) {
  return (
    <div
      data-control-ui="inline-attachment"
      data-control-family="inline-attachment"
      data-slot="actions"
      className={cn("flex items-center", className)}
      {...props}
    />
  );
}

export type InlineAttachmentActionProps = InlineAttachmentStyleProps<ComponentProps<"span">, InlineAttachmentKnobStyle>;

export function InlineAttachmentAction({ className, ...props }: InlineAttachmentActionProps) {
  return (
    <span data-control-ui="inline-attachment" data-control-family="inline-attachment" data-slot="action" className={className} {...props} />
  );
}

@layer components {
  :where([data-control-family="inline-attachment"][data-slot="root"]) {
    --cui-inline-attachment-background: var(--card);
    --cui-inline-attachment-hover-shadow: var(--shadow-md);
    --cui-inline-attachment-padding: calc(var(--spacing) * 3);
    --cui-inline-attachment-radius: var(--radius-field);
    --cui-inline-attachment-ring-color: var(--border);
    --cui-inline-attachment-image-outline-color: oklch(from var(--foreground) l c h / 0.1);
    --cui-inline-attachment-shadow: var(--shadow-sm);
    --cui-inline-attachment-content-background: oklch(from var(--background) l c h / 0.85);
    --cui-inline-attachment-content-foreground: var(--foreground);
    --cui-inline-attachment-content-radius: max(
      var(--radius-sm),
      calc(var(--cui-inline-attachment-radius) - var(--cui-inline-attachment-padding))
    );
    --cui-inline-attachment-content-shadow: var(--shadow-sm);
    --cui-inline-attachment-document-padding: calc(var(--spacing) * 5);
    --cui-inline-attachment-document-background: var(--muted);
    --cui-inline-attachment-document-background-image: none;
    border-radius: var(--cui-inline-attachment-radius);
    background: var(--cui-inline-attachment-background);
    box-shadow:
      inset 0 0 0 var(--control-rim-width) var(--cui-inline-attachment-ring-color),
      var(--cui-inline-attachment-shadow);
    text-align: left;
    transition-property: box-shadow;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="inline-attachment"][data-slot="root"]:focus-visible) {
    box-shadow:
      inset 0 0 0 var(--control-rim-width) var(--cui-inline-attachment-ring-color),
      var(--cui-inline-attachment-hover-shadow);
  }

  @media (hover: hover) {
    :where([data-control-family="inline-attachment"][data-slot="root"]:hover) {
      box-shadow:
        inset 0 0 0 var(--control-rim-width) var(--cui-inline-attachment-ring-color),
        var(--cui-inline-attachment-hover-shadow);
    }

    :where([data-control-family="inline-attachment"][data-slot="root"]:disabled:hover) {
      box-shadow:
        inset 0 0 0 var(--control-rim-width) var(--cui-inline-attachment-ring-color),
        var(--cui-inline-attachment-shadow);
    }
  }

  :where([data-control-family="inline-attachment"][data-slot="image"]) {
    border-radius: inherit;
  }

  :where([data-control-family="inline-attachment"][data-slot="media-image"]) {
    border-radius: inherit;
    outline: var(--control-rim-width) solid var(--cui-inline-attachment-image-outline-color);
    outline-offset: calc(var(--control-rim-width) * -1);
  }

  :where([data-control-family="inline-attachment"][data-slot="document"]) {
    padding: var(--cui-inline-attachment-document-padding);
    background: var(--cui-inline-attachment-document-background);
    background-image: var(--cui-inline-attachment-document-background-image);
  }

  :where([data-control-family="inline-attachment"][data-slot="document-sheet"]) {
    padding: calc(var(--spacing) * 4);
    border-radius: max(0px, calc(var(--cui-inline-attachment-radius) - var(--cui-inline-attachment-document-padding)));
    background: oklch(from var(--card) l c h / 0.78);
    box-shadow:
      inset 0 0 0 var(--control-rim-width) oklch(from var(--foreground) l c h / 0.1),
      var(--shadow-sm);
  }

  :where([data-control-family="inline-attachment"][data-slot="document-sheet"] > div) {
    margin-block-start: calc(var(--spacing) * 5);
    gap: calc(var(--spacing) * 2);
  }

  :where([data-control-family="inline-attachment"][data-slot="document-heading"]) {
    block-size: calc(var(--spacing) * 2);
    inline-size: calc(var(--spacing) * 20);
    border-radius: 9999px;
    background: oklch(from var(--foreground) l c h / 0.12);
  }

  :where([data-control-family="inline-attachment"][data-slot="document-line"]) {
    block-size: calc(var(--spacing) * 1.5);
    inline-size: calc(var(--spacing) * 44);
    border-radius: 9999px;
    background: oklch(from var(--foreground) l c h / 0.12);
  }

  :where([data-control-family="inline-attachment"][data-slot="document-line"][data-width="medium"]) {
    inline-size: calc(var(--spacing) * 36);
    background: oklch(from var(--foreground) l c h / 0.12);
  }

  :where([data-control-family="inline-attachment"][data-slot="document-line"][data-width="longest"]) {
    inline-size: calc(var(--spacing) * 48);
    background: oklch(from var(--foreground) l c h / 0.14);
  }

  :where([data-control-family="inline-attachment"][data-slot="document-line"][data-width="short"]) {
    inline-size: calc(var(--spacing) * 28);
    background: oklch(from var(--foreground) l c h / 0.1);
  }

  :where([data-control-family="inline-attachment"][data-slot="document-stamp"]) {
    margin-block-start: calc(var(--spacing) * 5);
    block-size: calc(var(--spacing) * 9);
    inline-size: calc(var(--spacing) * 24);
    border: var(--control-rim-width) dashed oklch(from var(--foreground) l c h / 0.18);
    border-radius: var(--radius-control);
  }

  :where([data-control-family="inline-attachment"][data-slot="content"]) {
    inset-inline: var(--cui-inline-attachment-padding);
    inset-block-end: var(--cui-inline-attachment-padding);
    padding-inline: calc(var(--spacing) * 3);
    padding-block: calc(var(--spacing) * 1);
    border-radius: var(--cui-inline-attachment-content-radius);
    background: var(--cui-inline-attachment-content-background);
    color: var(--cui-inline-attachment-content-foreground);
    box-shadow: var(--cui-inline-attachment-content-shadow);
    backdrop-filter: blur(var(--backdrop-blur-popover));
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="inline-attachment"][data-slot="description"]) {
    font-size: var(--text-micro);
    font-variant-numeric: tabular-nums;
    opacity: 0.65;
  }

  :where([data-control-family="inline-attachment"][data-slot="actions"]) {
    margin-block-start: calc(var(--spacing) * 1);
    gap: calc(var(--spacing) * 1);
  }

  :where([data-control-family="inline-attachment"][data-slot="action"]) {
    padding-inline: calc(var(--spacing) * 1.5);
    padding-block: calc(var(--spacing) * 0.5);
    border-radius: var(--radius-control);
    background: oklch(from var(--foreground) l c h / 0.08);
    font-size: var(--text-micro);
  }
}

@property --cui-inline-attachment-radius {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-inline-attachment-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-inline-attachment-ring-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-inline-attachment-padding {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-inline-attachment-document-padding {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-inline-attachment-document-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-inline-attachment-document-background-image {
  syntax: "*";
  inherits: true;
}

@property --cui-inline-attachment-shadow {
  syntax: "*";
  inherits: true;
}

@property --cui-inline-attachment-hover-shadow {
  syntax: "*";
  inherits: true;
}

@property --cui-inline-attachment-content-radius {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-inline-attachment-content-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-inline-attachment-content-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-inline-attachment-content-shadow {
  syntax: "*";
  inherits: true;
}

@property --cui-inline-attachment-image-outline-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}
